{"path": "/app/bin/boards.py", "content": "#!/usr/bin/env python3
"""Build departure boards from a timetable feed.

Usage: python3 boards.py INPUT_DIR OUTPUT_FILE
"""
import csv
import datetime as dt
import io
import json
import os
import sys
from zoneinfo import ZoneInfo

UTC = dt.timezone.utc


def read_csv(path):
    if not os.path.isfile(path):
        return []
    with open(path, "rb") as f:
        text = f.read().decode("utf-8-sig")
    reader = csv.reader(io.StringIO(text, newline=""))
    header = None
    rows = []
    for raw in reader:
        cells = [c.strip() for c in raw]
        if not any(cells):
            continue
        if header is None:
            header = [c.lstrip("\ufeff") for c in cells]
            continue
        row = {}
        for i, name in enumerate(header):
            row[name] = cells[i] if i < len(cells) else ""
        rows.append(row)
    return rows


def parse_time(s):
    h, m, sec = s.strip().split(":")
    return int(h) * 3600 + int(m) * 60 + int(sec)


def to_int(s, default=0):
    s = (s or "").strip()
    if not s:
        return default
    return int(s)


def parse_date(s):
    s = s.strip()
    return dt.date(int(s[0:4]), int(s[4:6]), int(s[6:8]))


_zones = {}


def zone(name):
    z = _zones.get(name)
    if z is None:
        z = _zones[name] = ZoneInfo(name)
    return z


def fmt(instant, tzname):
    local = instant.astimezone(zone(tzname))
    return local.isoformat(timespec="seconds")


def main(indir, outfile):
    def rd(name):
        return read_csv(os.path.join(indir, name))

    agencies = rd("agency.txt")
    stops = {r["stop_id"]: r for r in rd("stops.txt")}
    routes = {r["route_id"]: r for r in rd("routes.txt")}
    trips = {r["trip_id"]: r for r in rd("trips.txt")}
    calendar = {r["service_id"]: r for r in rd("calendar.txt")}
    cal_dates = {}
    for r in rd("calendar_dates.txt"):
        cal_dates[(r["service_id"], parse_date(r["date"]))] = to_int(r["exception_type"])
    freqs = {}
    for r in rd("frequencies.txt"):
        freqs.setdefault(r["trip_id"], []).append(r)

    with open(os.path.join(indir, "request.json"), encoding="utf-8-sig") as f:
        request = json.load(f)
    dates = sorted({dt.date.fromisoformat(d) for d in request["service_dates"]})

    agency_tz = {}
    for a in agencies:
        agency_tz[a["agency_id"]] = a["agency_timezone"]
    first_agency = agencies[0]
    default_tz = first_agency["agency_timezone"]

    def route_agency(route):
        aid = route.get("agency_id", "")
        if aid in agency_tz:
            return aid
        return first_agency["agency_id"]

    # stop times per trip
    st_by_trip = {}
    for r in rd("stop_times.txt"):
        st_by_trip.setdefault(r["trip_id"], []).append(r)

    # board stops
    def board_of(stop_id):
        s = stops[stop_id]
        parent = s.get("parent_station", "")
        if parent:
            return parent
        return stop_id

    board_stops = {}
    for sid, s in stops.items():
        lt = to_int(s.get("location_type"))
        if lt == 1 or (lt == 0 and not s.get("parent_station", "")):
            board_stops[sid] = s

    def board_tz(sid):
        return board_stops[sid].get("stop_timezone", "") or default_tz

    # Trip patterns (independent of date)
    patterns = {}
    for tid, rows in st_by_trip.items():
        trip = trips[tid]
        rows = sorted(rows, key=lambda r: to_int(r["stop_sequence"]))
        n = len(rows)
        times = []
        for r in rows:
            t = r.get("departure_time", "") or r.get("arrival_time", "")
            times.append(parse_time(t) if t else None)
        known = [i for i, t in enumerate(times) if t is not None]
        for i in range(n):
            if times[i] is not None:
                continue
            b = max(k for k in known if k < i)
            a = min(k for k in known if k > i)
            times[i] = times[b] + ((times[a] - times[b]) * (i - b)) // (a - b)
        last = stops[rows[-1]["stop_id"]]
        last_name = stops[board_of(rows[-1]["stop_id"])]["stop_name"] if last.get("parent_station", "") else last["stop_name"]
        route = routes[trip["route_id"]]
        label = route.get("route_short_name", "") or route.get("route_long_name", "")
        aid = route_agency(route)
        deps = []
        for i, r in enumerate(rows):
            if i == n - 1:
                continue
            if to_int(r.get("pickup_type")) == 1:
                continue
            headsign = r.get("stop_headsign", "") or trip.get("trip_headsign", "") or last_name
            stop = stops[r["stop_id"]]
            deps.append({
                "time": times[i],
                "offset": times[i] - times[0],
                "board": board_of(r["stop_id"]),
                "headsign": headsign,
                "platform": stop.get("platform_code", "") or None,
            })
        patterns[tid] = (label, aid, deps)

    def runs(service_id, d):
        ex = cal_dates.get((service_id, d))
        if ex == 1:
            return True
        if ex == 2:
            return False
        c = calendar.get(service_id)
        if c is None:
            return False
        if not (parse_date(c["start_date"]) <= d <= parse_date(c["end_date"])):
            return False
        return to_int(c[["monday", "tuesday", "wednesday", "thursday", "friday",
                         "saturday", "sunday"][d.weekday()]]) == 1

    boards = {}
    for sid in board_stops:
        for d in dates:
            boards[(sid, d)] = []

    for d in dates:
        for tid, (label, aid, deps) in patterns.items():
            trip = trips[tid]
            if not runs(trip["service_id"], d):
                continue
            tz = zone(agency_tz[aid])
            noon = dt.datetime(d.year, d.month, d.day, 12, 0, 0, tzinfo=tz)
            origin = noon.astimezone(UTC) - dt.timedelta(hours=12)

            def inst(secs):
                return origin + dt.timedelta(seconds=secs)

            entries = []  # (kind, start_secs, until_secs, headway, dep)
            if tid in freqs:
                for w in freqs[tid]:
                    start = parse_time(w["start_time"])
                    end = parse_time(w["end_time"])
                    hw = to_int(w["headway_secs"])
                    exact = to_int(w.get("exact_times")) == 1
                    if start >= end or hw <= 0:
                        continue
                    starts = list(range(start, end, hw))
                    for dep in deps:
                        if exact:
                            for s in starts:
                                entries.append(("scheduled", s + dep["offset"], None, None, dep))
                        else:
                            entries.append(("interval", starts[0] + dep["offset"],
                                            starts[-1] + dep["offset"], hw, dep))
            else:
                for dep in deps:
                    entries.append(("scheduled", dep["time"], None, None, dep))
            for kind, t, u, hw, dep in entries:
                key = dep["board"]
                if (key, d) not in boards:
                    continue
                boards[(key, d)].append((inst(t), label, dep["headsign"], tid,
                                         dep["platform"], kind,
                                         inst(u) if u is not None else None, hw, aid))

    out_boards = []
    for (sid, d) in sorted(boards, key=lambda k: (k[0], k[1])):
        tzname = board_tz(sid)
        items = sorted(boards[(sid, d)],
                       key=lambda e: (e[0], e[1], e[2], e[3], (0, "") if e[4] is None else (1, e[4])))
        departures = []
        for instant, label, headsign, tid, platform, kind, until, hw, aid in items:
            departures.append({
                "kind": kind,
                "time": fmt(instant, tzname),
                "until": fmt(until, tzname) if until is not None else None,
                "headway_secs": hw,
                "route": label,
                "headsign": headsign,
                "trip": tid,
                "platform": platform,
                "agency": aid,
            })
        out_boards.append({
            "stop_id": sid,
            "name": board_stops[sid]["stop_name"],
            "timezone": tzname,
            "service_date": d.isoformat(),
            "departures": departures,
        })

    result = {"service_dates": [d.isoformat() for d in dates], "boards": out_boards}
    with open(outfile, "w", encoding="utf-8") as f:
        json.dump(result, f, ensure_ascii=False)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
"}
